    mugs = parse_objects('visible mugs')
    fridges = parse_objects('visible fridge')
    if acquire_object(mugs[0]):
        load_washing_machine(mugs[0], fridges[0])
    return parse_question('am I holding a mug?')

def acquire_object(item):
    """Return True on success and False when a prerequisite or action fails."""
    if is_holding(item):
        return True
    if walk(item).status != 'succeeded':
        return False
    return grab(item).status == 'succeeded'

def load_washing_machine(clothes, machine):
    """Return True on success and False when a prerequisite or action fails."""
    if not place_held_in_container(clothes, machine):
        return False
    return close(machine).status == 'succeeded'

def place_held_in_container(item, container):
    """Return True on success and False when a prerequisite or action fails."""
    if not is_holding(item):
        return False
    if not ensure_open(container):
        return False
    return putin(item, container).status == 'succeeded'

def ensure_open(container):
    """Return True on success and False when a prerequisite or action fails."""
    if walk(container).status != 'succeeded':
        return False
    states = get_object_states(container)
    if states is None:
        return False
    return 'OPEN' in states or open(container).status == 'succeeded'

